#!/bin/bash
# Wizard template — generated by ABSOLUTE Stack /wizard
# Walks a human step-by-step through a manual procedure.
# Usage: bash wizard-SERVICE.sh

set -euo pipefail

# ---- Display helpers ----
TOTAL_STAGES=${TOTAL_STAGES:-1}
TOTAL_MINUTES=${TOTAL_MINUTES:-10}
STAGE_NUM=0
trap 'echo " Interrupted. You can restart — stages already done are safe."; exit 130' INT

open_url() {
  case "$(uname -s)" in
    Darwin) open "$1" ;;
    Linux) xdg-open "$1" 2>/dev/null || sensible-browser "$1" 2>/dev/null || echo "  Open: $1" ;;
    CYGWIN*|MINGW32*|MSYS*|MINGW*) start "$1" ;;
    *) echo "  Open: $1" ;;
  esac
}

say() { echo -e "\n  $*"; }
step() { echo "  → $*"; }
pause() { echo; read -rp "  Press Enter when done..."; }
confirm() {
  echo
  read -rp "  $* [y/N] " REPLY
  case "$REPLY" in [yY]|[yY][eE][sS]) return 0 ;; *) return 1 ;; esac
}

ask() {
  local var=$1 prompt=$2 default=$3
  if [ -n "$default" ]; then
    read -rp "  $prompt [$default]: " REPLY
    eval "$var=\"${REPLY:-$default}\""
  else
    read -rp "  $prompt: " REPLY
    eval "$var=\"$REPLY\""
  fi
}

ask_secret() {
  local var=$1 prompt=$2
  echo -n "  $prompt: "
  read -rs REPLY
  echo
  eval "$var=\"$REPLY\""
}

write_env() {
  local key=$1 value=$2
  local env_file="${3:-.env}"
  if grep -q "^${key}=" "$env_file" 2>/dev/null; then
    sed -i "s|^${key}=.*|${key}=${value}|" "$env_file"
  else
    echo "${key}=${value}" >> "$env_file"
  fi
  echo "  -> wrote ${key}=[...] to ${env_file}"
}

set_secret() {
  local name=$1 value=$2
  if command -v gh &>/dev/null; then
    echo "$value" | gh secret set "$name" --body - 2>/dev/null && echo "  -> set GitHub secret: $name" || echo "  (gh not configured, skipping $name)"
  fi
}

set_var() {
  local name=$1 value=$2
  if command -v gh &>/dev/null; then
    echo "$value" | gh variable set "$name" --body - 2>/dev/null && echo "  -> set GitHub variable: $name" || echo "  (gh not configured, skipping $name)"
  fi
}

stage() {
  STAGE_NUM=$((STAGE_NUM + 1))
  local elapsed=$(( (STAGE_NUM - 1) * TOTAL_MINUTES * 60 / TOTAL_STAGES ))
  local remaining=$(( TOTAL_MINUTES * 60 - elapsed ))
  local min_rem=$(( remaining / 60 ))
  local sec_rem=$(( remaining % 60 ))
  clear 2>/dev/null || true
  printf "\n"
  printf "  %s of %s — approx %dm %ds remaining\n\n" "$STAGE_NUM" "$TOTAL_STAGES" "$min_rem" "$sec_rem"
  printf "  ╔══════════════════════════════════════╗\n"
  printf "  ║  Step %d: %-26s ║\n" "$STAGE_NUM" "$1"
  printf "  ╚══════════════════════════════════════╝\n"
  echo
}

summary() {
  echo
  echo "  ╔══════════════════════════════════════╗"
  echo "  ║        All done!                     ║"
  echo "  ╚══════════════════════════════════════╝"
  echo
  echo "  What was set up:"
  echo "  $*"
}

# ============================================
# STAGES — replace below
# ============================================

echo
echo "  ===================================="
echo "  Wizard: SERVICE_NAME"
echo "  ===================================="
echo

# Example stage:
# stage "Get API key"
# open_url "https://example.com/settings/api"
# step "Click Create Key, copy the value"
# ask_secret API_KEY "Paste the API key"
# write_env "SERVICE_API_KEY" "$API_KEY"
# set_secret "SERVICE_API_KEY" "$API_KEY"
# pause

echo
echo "  Nothing configured yet."
echo "  Edit this script to add your stages."
echo
echo "  Run: bash <(curl -fsSL https://raw.githubusercontent.com/mattpocock/skills/main/skills/in-progress/wizard/template.sh | sed -n '1,/^# STAGES/p')"
echo

# ============================================
# SUMMARY — update below
# ============================================

summary "SERVICE_NAME configured"
